options.dotDiagram:
digraph nexus_rag {
  // Issue #133: the system flow as DOT rather than hand-placed SVG. Graphviz
  // does the routing, so a new component is a line of code instead of a
  // coordinate hunt -- and edges cannot be left crossing by accident.
  rankdir=LR;
  bgcolor="transparent";
  compound=true;
  nodesep=0.30;
  ranksep=0.55;
  fontname="Inter, system-ui, sans-serif";

  node [shape=box style="filled,rounded" fontname="Inter, system-ui, sans-serif"
        fontsize=13 fontcolor="#ffffff" color="#0d1117" penwidth=1.4
        fillcolor="#20252e" width=1.9 height=0.55 margin="0.16,0.09"];
  edge [fontname="Inter, system-ui, sans-serif" fontsize=11 fontcolor="#e8eef7"
        color="#556072" penwidth=2.0 arrowsize=0.8];

  // Node ids are the component names the node-status query returns in its
  // `component` label, so one override rule colours every node.
  subgraph cluster_auth {
    label="AUTHENTICATION"; fontsize=11; fontcolor="#a9b4c4"; color="#3a4454";
    style="rounded"; penwidth=1;
    librechat [label="LibreChat\nchat UI · HTTPS"];
    keycloak  [label="Keycloak\nOIDC / SSO"];
  }

  subgraph cluster_ingest {
    label="INGESTION"; fontsize=11; fontcolor="#a9b4c4"; color="#3a4454";
    style="rounded"; penwidth=1;
    "ingestion-api"    [label="ingestion-api\nupload · tag · create"];
    nats               [label="NATS\nJetStream queue" shape=hexagon width=2.1];
    "ingestion-worker" [label="ingestion-worker\nparse · chunk · embed"];
    qdrant             [label="Qdrant\nvector store · shared" shape=cylinder];
    "object-store"     [label="object store\noriginal bytes (NFR-12)" shape=cylinder fillcolor="#33405a"];
    postgres           [label="Postgres\ndocuments · status · audit" shape=cylinder];
  }

  subgraph cluster_retrieval {
    label="RETRIEVAL"; fontsize=11; fontcolor="#a9b4c4"; color="#3a4454";
    style="rounded"; penwidth=1;
    "orchestration-mcp" [label="orchestration-mcp\nrag_search via MCP"];
    reranker            [label="reranker\ncross-encoder"];
  }

  subgraph cluster_generation {
    label="GENERATION"; fontsize=11; fontcolor="#a9b4c4"; color="#3a4454";
    style="rounded"; penwidth=1;
    litellm [label="LiteLLM\nmodel gateway"];
    ollama  [label="Ollama\nembed + generate · shared"];
  }

  // Edge ids match the `edge` label the hop-activity query returns.
  keycloak            -> librechat            [id="edge-auth"     label="OIDC"];
  librechat           -> "ingestion-api"      [id="edge-upload"   label="upload"];
  "ingestion-api"     -> nats                 [id="edge-publish"  label="publish"];
  nats                -> "ingestion-worker"   [id="edge-consume"  label="consume"];
  "ingestion-worker"  -> qdrant               [id="edge-upsert"   label="write vectors"];
  "ingestion-api"     -> "object-store"       [id="edge-objstore" label="original file" penwidth=1.2 style=dashed];
  "ingestion-worker"  -> postgres             [id="edge-status"   label="status / audit" penwidth=1.2 style=dashed];
  "ingestion-worker"  -> ollama               [id="edge-embedI"   label="embed" penwidth=1.2 style=dashed];
  librechat           -> "orchestration-mcp"  [id="edge-query"    label="query"];
  "orchestration-mcp" -> qdrant               [id="edge-vquery"   label="retrieve · dense + BM25"];
  "orchestration-mcp" -> reranker             [id="edge-rerank"   label="rerank"];
  "orchestration-mcp" -> ollama               [id="edge-embedQ"   label="embed query" penwidth=1.2 style=dashed];
  librechat           -> litellm              [id="edge-genin"    label="prompt"];
  litellm             -> ollama               [id="edge-gen"      label="generate"];
}
